-- Updates the wording, ingredients and dietary tags of the existing menu rows
-- (matched by dish name) so they describe the new photos.
-- Run it in the Neon SQL Editor, on the same database your Vercel site uses.
-- It only changes existing rows: no inserts, no deletes. Safe to run twice.

UPDATE menu_items SET description = 'Smashed avocado on toasted seeded sourdough, topped with a fried egg, chili flakes and fresh chives.', ingredients = ARRAY['Sourdough bread', 'Avocado', 'Fried egg', 'Chili flakes', 'Chives']::text[], dietary_tags = ARRAY['vegetarian']::text[], updated_at = now() WHERE name = 'Avocado Toast';
UPDATE menu_items SET description = 'Thick Greek yogurt topped with raspberries, blackberries and blueberries, finished with crunchy granola.', ingredients = ARRAY['Greek yogurt', 'Mixed berries', 'Granola']::text[], dietary_tags = ARRAY['vegetarian']::text[], updated_at = now() WHERE name = 'Greek Yogurt Bowl';
UPDATE menu_items SET description = 'Grilled chicken over crisp greens with roasted butternut squash, apple, dried cranberries, pecans, bacon, crumbled cheese and a boiled egg, in a house vinaigrette.', ingredients = ARRAY['Grilled chicken', 'Mixed greens', 'Butternut squash', 'Apple', 'Dried cranberries', 'Pecans', 'Bacon', 'Crumbled cheese', 'Boiled egg', 'Cherry tomatoes']::text[], dietary_tags = ARRAY[]::text[], updated_at = now() WHERE name = 'Grilled Chicken Salad';
UPDATE menu_items SET description = 'Penne tossed in house-made basil pesto with pine nuts and shaved parmesan.', ingredients = ARRAY['Penne pasta', 'Basil pesto', 'Pine nuts', 'Parmesan']::text[], dietary_tags = ARRAY['vegetarian']::text[], updated_at = now() WHERE name = 'Pesto Penne';
UPDATE menu_items SET description = 'Spice-crusted salmon fillets with asparagus, peas, baby potatoes and cherry tomatoes, finished with fresh lemon and herbs.', ingredients = ARRAY['Salmon', 'Asparagus', 'Green peas', 'Baby potatoes', 'Cherry tomatoes', 'Lemon']::text[], dietary_tags = ARRAY['gluten-free']::text[], updated_at = now() WHERE name = 'Pan-Seared Salmon';
UPDATE menu_items SET description = '21-day dry-aged ribeye, grilled and finished with rosemary butter and roasted garlic.', ingredients = ARRAY['Ribeye steak', 'Rosemary butter', 'Roasted garlic']::text[], dietary_tags = ARRAY['gluten-free']::text[], updated_at = now() WHERE name = 'Ribeye Steak';
UPDATE menu_items SET description = 'Slow-cooked arborio rice with chanterelle and wild mushrooms, finished with butter, parmesan and truffle oil.', ingredients = ARRAY['Arborio rice', 'Wild mushrooms', 'Truffle oil', 'Parmesan']::text[], dietary_tags = ARRAY['vegetarian', 'gluten-free']::text[], updated_at = now() WHERE name = 'Wild Mushroom Risotto';
UPDATE menu_items SET description = 'A classic double shot, locally roasted.', ingredients = ARRAY['Espresso']::text[], dietary_tags = ARRAY['vegan', 'vegetarian', 'gluten-free']::text[], updated_at = now() WHERE name = 'Espresso';
UPDATE menu_items SET description = 'Espresso steamed with oat milk.', ingredients = ARRAY['Espresso', 'Oat milk']::text[], dietary_tags = ARRAY['vegan', 'vegetarian']::text[], updated_at = now() WHERE name = 'Oat Milk Latte';
UPDATE menu_items SET description = 'House-carbonated water with fresh lime, orange slices and mint.', ingredients = ARRAY['Sparkling water', 'Fresh lime', 'Orange slices', 'Mint leaves']::text[], dietary_tags = ARRAY['vegan', 'vegetarian', 'gluten-free']::text[], updated_at = now() WHERE name = 'Sparkling Lime';
UPDATE menu_items SET description = 'Warm dark chocolate cake with a molten center, served with vanilla ice cream and fresh raspberries.', ingredients = ARRAY['Dark chocolate', 'Vanilla ice cream', 'Raspberries', 'Mint leaves']::text[], dietary_tags = ARRAY['vegetarian']::text[], updated_at = now() WHERE name = 'Dark Chocolate Lava Cake';

-- check: should list all 11 dishes with the new text
SELECT name, dietary_tags, description FROM menu_items ORDER BY id;
